proc caPrimary*(): string {.raises: [IOError].} =
  ## The Capability Authority contract (CA l.143 to l.1244), its nine blocks
  ## joined with a blank line between them.
  for i, p in caParts:
    if i > 0:
      result.add("\n")
    result.add(readFile(p))

proc caSet(): Result[ContractSet, string] =
